package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync/atomic"
	"time"
)

type FileMeta struct {
	ID         int    `json:"id"`
	Name       string `json:"name"`
	Size       int    `json:"size"`
	Type       string `json:"type"`
	UploadedAt string `json:"uploadedAt"`
}

var fileMeta = map[int]FileMeta{}
var fileID int64

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/upload", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "POST" { http.NotFound(w, r); return }
		r.ParseMultipartForm(32 << 20)
		fh, header, _ := r.FormFile("file")
		defer fh.Close()
		data, _ := io.ReadAll(fh)
		id := int(atomic.AddInt64(&fileID, 1))
		meta := FileMeta{ID: id, Name: header.Filename, Size: len(data), Type: header.Header.Get("Content-Type"), UploadedAt: time.Now().UTC().Format(time.RFC3339)}
		fileMeta[id] = meta
		json.NewEncoder(w).Encode(meta)
	})

	http.HandleFunc("/files/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		path := strings.TrimPrefix(r.URL.Path, "/files/")
		if strings.HasSuffix(path, "/metadata") {
			idStr := strings.TrimSuffix(path, "/metadata")
			id, _ := strconv.Atoi(strings.TrimSuffix(idStr, "/"))
			meta, ok := fileMeta[id]
			if !ok { w.WriteHeader(404); json.NewEncoder(w).Encode(map[string]string{"error": "Not found"}); return }
			json.NewEncoder(w).Encode(meta)
		}
	})

	http.HandleFunc("/files", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		var list []FileMeta
		for _, m := range fileMeta { list = append(list, m) }
		json.NewEncoder(w).Encode(list)
	})

	http.ListenAndServe(":"+port, nil)
	_ = fmt.Sprintf("%s", "")
}
